css:
:root {
  --bg-top: #667eea;
  --bg-bottom: #764ba2;
  --accent: #5b6ee8;
  --accent-soft: #eef1fd;
  --text-main: #1f2430;
  --text-sub: #7b8194;
  --text-on-gradient: #ffffff;
  --code-bg: #f4f6fb;
  --code-border: #e3e7f2;
  --answer-color: #2f3542;
}

/* ---------- 卡片整体 ---------- */
.card {
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 19px;
  line-height: 1.85;
  color: var(--text-main);
  background: #ffffff;
  border-radius: 20px;
  box-shadow: 0 10px 30px rgba(90, 100, 160, 0.18);
  padding: 30px 34px 34px;
  margin: 6px auto;
  max-width: 760px;
  text-align: left;
  border: 1px solid #eef0f8;
}

/* ---------- 顶部渐变条 ---------- */
.card::before {
  content: "";
  display: block;
  height: 6px;
  margin: -30px -34px 26px;
  border-radius: 20px 20px 0 0;
  background: linear-gradient(90deg, var(--bg-top), var(--bg-bottom));
}

/* ---------- 标签行 ---------- */
.topbar {
  display: flex;
  gap: 8px;
  margin-bottom: 18px;
}
.badge {
  display: inline-block;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.4px;
  color: var(--text-on-gradient);
  background: linear-gradient(135deg, var(--bg-top), var(--bg-bottom));
  padding: 4px 14px;
  border-radius: 999px;
  box-shadow: 0 3px 8px rgba(102, 126, 234, 0.35);
}
.badge.soft {
  background: var(--accent-soft);
  color: var(--accent);
  box-shadow: none;
}

/* ---------- 问题 ---------- */
.front-q {
  font-size: 23px;
  font-weight: 700;
  color: var(--text-main);
  line-height: 1.6;
  margin-bottom: 6px;
}
.answer-q {
  font-size: 17px;
  font-weight: 600;
  color: var(--text-sub);
  line-height: 1.6;
  margin-bottom: 4px;
  padding-bottom: 16px;
  border-bottom: 1px dashed #e4e8f4;
}

/* ---------- 答案 ---------- */
.answer {
  margin-top: 18px;
  font-size: 19px;
  color: var(--answer-color);
}
.answer b {
  color: #3d52d5;
}

/* ---------- 代码 ---------- */
code {
  font-family: "JetBrains Mono", "Cascadia Code", Consolas, monospace;
  font-size: 0.88em;
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  color: #d6336c;
  padding: 2px 7px;
  border-radius: 7px;
}
pre {
  font-family: "JetBrains Mono", "Cascadia Code", Consolas, monospace;
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  border-left: 4px solid var(--accent);
  color: #27406e;
  padding: 12px 16px;
  border-radius: 10px;
  font-size: 16px;
  line-height: 1.6;
  overflow-x: auto;
}

/* ---------- 分隔线 ---------- */
hr {
  border: none;
  border-top: 1px dashed #e4e8f4;
  margin: 20px 0;
}

/* ---------- 提示文字(正面底部) ---------- */
.hint {
  margin-top: 26px;
  font-size: 13px;
  color: var(--text-sub);
  text-align: center;
  letter-spacing: 1px;
}
.hint::before {
  content: "▼ ";
  color: var(--accent);
}

/* ---------- 夜间模式 ---------- */
.nightMode .card {
  background: #232733;
  border-color: #30364a;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
}
.nightMode .front-q,
.nightMode .answer,
.nightMode .answer-q {
  color: #e8eaf2;
}
.nightMode .answer b {
  color: #9fb0ff;
}
.nightMode .badge.soft {
  background: #2c3150;
  color: #a8b4ff;
}
.nightMode code {
  background: #1b1f2b;
  border-color: #2f3550;
  color: #ff8fb8;
}
.nightMode pre {
  background: #1b1f2b;
  border-color: #2f3550;
  color: #b8c6e8;
}
.nightMode .answer-q,
.nightMode .hint {
  color: #8b93ad;
}
.nightMode .answer-q {
  border-bottom-color: #333a52;
}
.nightMode hr {
  border-top-color: #333a52;
}
